// Cloudflare Worker: vconnect-maintenance
// Multi-Domain Adaptive Maintenance Gateway for connecto.fun
// Handles connecto.fun, news.connecto.fun, and resinora.connecto.fun

const CONNECTO_MAIN_HTML = "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0, maximum-scale=1.0, user-scalable=no\">\n  <title>Connecto \u2022 Scheduled Maintenance</title>\n  <link rel=\"icon\" type=\"image/svg+xml\" href=\"data:image/svg+xml,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 100 100'><rect width='100' height='100' rx='22' fill='%23111827'/><path d='M30 35h40a6 6 0 0 1 6 6v22a6 6 0 0 1-6 6H45L30 78V41a6 6 0 0 1 6-6z' fill='%23FFFFFF'/><circle cx='42' cy='52' r='4' fill='%236366F1'/><circle cx='58' cy='52' r='4' fill='%236366F1'/></svg>\">\n  <style>\n    *, *::before, *::after {\n      box-sizing: border-box;\n      margin: 0;\n      padding: 0;\n    }\n    :root {\n      --bg: #0b0d13;\n      --card-bg: #12151e;\n      --text-title: #ffffff;\n      --text-sub: #9ca3af;\n      --text-muted: #6b7280;\n      --border: #1f2430;\n      --border-subtle: rgba(255, 255, 255, 0.07);\n      --button-bg: #ffffff;\n      --button-text: #0b0d13;\n      --button-hover: #f3f4f6;\n      --accent: #4f46e5;\n      --accent-tint: rgba(99, 102, 241, 0.12);\n      --amber: #f59e0b;\n      --emerald: #10b981;\n    }\n\n    * { box-sizing: border-box; margin: 0; padding: 0; }\n\n    body {\n      background-color: var(--bg);\n      background-image: \n        radial-gradient(circle at 50% -10%, rgba(99, 102, 241, 0.15) 0%, transparent 60%),\n        radial-gradient(circle at 50% 110%, rgba(56, 189, 248, 0.08) 0%, transparent 50%);\n      color: var(--text-sub);\n      font-family: -apple-system, BlinkMacSystemFont, \"Segoe UI\", Roboto, Helvetica, Arial, sans-serif;\n      min-height: 100vh;\n      display: flex;\n      flex-direction: column;\n      justify-content: space-between;\n      align-items: center;\n      padding: 44px 24px 32px;\n      line-height: 1.6;\n      -webkit-font-smoothing: antialiased;\n      text-align: center;\n      overflow-x: hidden;\n      position: relative;\n    }\n\n    /* Ambient Subtle Background Breathing */\n    body::before {\n      content: '';\n      position: absolute;\n      top: 0; left: 0; right: 0; bottom: 0;\n      background: radial-gradient(circle at 50% 30%, rgba(255, 255, 255, 0.02) 0%, transparent 60%);\n      pointer-events: none;\n      animation: ambientBreathe 8s ease-in-out infinite alternate;\n    }\n    @keyframes ambientBreathe {\n      0% { opacity: 0.4; transform: scale(0.98); }\n      100% { opacity: 1; transform: scale(1.02); }\n    }\n\n    /* Orchestrated Entrance Animation Stagger */\n    .animate-entry {\n      opacity: 0;\n      transform: translateY(16px);\n      animation: entryFadeUp 0.7s cubic-bezier(0.16, 1, 0.3, 1) forwards;\n    }\n    .delay-1 { animation-delay: 0.08s; }\n    .delay-2 { animation-delay: 0.18s; }\n    .delay-3 { animation-delay: 0.28s; }\n    .delay-4 { animation-delay: 0.38s; }\n    .delay-5 { animation-delay: 0.48s; }\n    .delay-6 { animation-delay: 0.58s; }\n\n    @keyframes entryFadeUp {\n      0% { opacity: 0; transform: translateY(16px); }\n      100% { opacity: 1; transform: translateY(0); }\n    }\n\n    /* Top Brand */\n    .brand-link {\n      display: inline-flex;\n      align-items: center;\n      gap: 10px;\n      text-decoration: none;\n      color: var(--text-title);\n      font-size: 19px;\n      font-weight: 700;\n      letter-spacing: -0.4px;\n      transition: transform 0.25s cubic-bezier(0.16, 1, 0.3, 1);\n      position: relative;\n      z-index: 10;\n    }\n    .brand-link:hover { transform: translateY(-1px); }\n    .brand-symbol {\n      width: 32px;\n      height: 32px;\n      border-radius: 9px;\n      background: #181d28;\n      border: 1px solid var(--border);\n      display: flex;\n      align-items: center;\n      justify-content: center;\n      transition: border-color 0.2s, box-shadow 0.2s;\n    }\n    .brand-link:hover .brand-symbol {\n      border-color: rgba(255, 255, 255, 0.25);\n      box-shadow: 0 0 12px rgba(255, 255, 255, 0.1);\n    }\n    .brand-symbol svg { width: 17px; height: 17px; fill: #ffffff; }\n\n    /* Center Content Container */\n    main.center-box {\n      width: 100%;\n      max-width: 520px;\n      margin: 32px auto;\n      display: flex;\n      flex-direction: column;\n      align-items: center;\n      position: relative;\n      z-index: 10;\n    }\n\n    /* Bespoke Animated Editorial Mechanical Clock */\n    .clock-stage {\n      width: 68px;\n      height: 68px;\n      border-radius: 20px;\n      background: rgba(255, 255, 255, 0.03);\n      border: 1px solid var(--border);\n      box-shadow: \n        0 0 0 1px rgba(255, 255, 255, 0.04),\n        0 10px 25px rgba(0, 0, 0, 0.4);\n      display: flex;\n      align-items: center;\n      justify-content: center;\n      margin-bottom: 28px;\n      position: relative;\n      transition: transform 0.4s cubic-bezier(0.34, 1.56, 0.64, 1), box-shadow 0.4s;\n      cursor: pointer;\n    }\n    .clock-stage:hover {\n      transform: scale(1.06) rotate(4deg);\n      box-shadow: \n        0 0 0 1px rgba(255, 255, 255, 0.15),\n        0 16px 36px rgba(0, 0, 0, 0.5),\n        0 0 20px rgba(99, 102, 241, 0.2);\n    }\n\n    /* Clock SVG Hands */\n    .clock-svg {\n      width: 34px;\n      height: 34px;\n    }\n    .clock-face {\n      fill: none;\n      stroke: #4b5563;\n      stroke-width: 2;\n    }\n    .clock-hand-hour {\n      stroke: #9ca3af;\n      stroke-width: 2;\n      stroke-linecap: round;\n      transform-origin: 17px 17px;\n      animation: rotateHour 48s linear infinite;\n    }\n    .clock-hand-minute {\n      stroke: #e5e7eb;\n      stroke-width: 1.8;\n      stroke-linecap: round;\n      transform-origin: 17px 17px;\n      animation: rotateMinute 12s linear infinite;\n    }\n    .clock-hand-second {\n      stroke: var(--accent);\n      stroke-width: 1.2;\n      stroke-linecap: round;\n      transform-origin: 17px 17px;\n      animation: rotateSecond 4s linear infinite;\n    }\n    .clock-center-dot {\n      fill: #ffffff;\n    }\n\n    @keyframes rotateHour { 0% { transform: rotate(0deg); } 100% { transform: rotate(360deg); } }\n    @keyframes rotateMinute { 0% { transform: rotate(0deg); } 100% { transform: rotate(360deg); } }\n    @keyframes rotateSecond { 0% { transform: rotate(0deg); } 100% { transform: rotate(360deg); } }\n\n    /* Clean Status Pill with Pulsing Ambient Dot */\n    .status-badge {\n      display: inline-flex;\n      align-items: center;\n      gap: 8px;\n      padding: 5px 14px;\n      border-radius: 20px;\n      background: rgba(245, 158, 11, 0.08);\n      border: 1px solid rgba(245, 158, 11, 0.25);\n      font-size: 12px;\n      font-weight: 600;\n      color: #fbbf24;\n      margin-bottom: 22px;\n      letter-spacing: 0.2px;\n    }\n    .status-dot-pulse {\n      width: 7px;\n      height: 7px;\n      border-radius: 50%;\n      background: #f59e0b;\n      box-shadow: 0 0 8px rgba(245, 158, 11, 0.6);\n      animation: pulseDot 2s infinite ease-in-out;\n    }\n    @keyframes pulseDot {\n      0%, 100% { transform: scale(1); opacity: 1; }\n      50% { transform: scale(1.3); opacity: 0.5; }\n    }\n\n    /* Editorial Typography */\n    h1.heading {\n      color: var(--text-title);\n      font-size: 32px;\n      font-weight: 700;\n      letter-spacing: -0.8px;\n      line-height: 1.25;\n      margin-bottom: 16px;\n    }\n    p.body-text {\n      font-size: 15.5px;\n      color: var(--text-sub);\n      line-height: 1.65;\n      margin-bottom: 30px;\n    }\n\n    /* Actions Group */\n    .button-group {\n      display: flex;\n      align-items: center;\n      gap: 12px;\n      margin-bottom: 24px;\n      flex-wrap: wrap;\n      justify-content: center;\n    }\n\n    .btn-refresh {\n      background: var(--button-bg);\n      color: var(--button-text);\n      border: none;\n      padding: 11px 26px;\n      border-radius: 24px;\n      font-size: 14px;\n      font-weight: 600;\n      cursor: pointer;\n      text-decoration: none;\n      display: inline-flex;\n      align-items: center;\n      gap: 8px;\n      box-shadow: 0 4px 14px rgba(0, 0, 0, 0.25);\n      transition: all 0.2s cubic-bezier(0.16, 1, 0.3, 1);\n    }\n    .btn-refresh:hover {\n      background: var(--button-hover);\n      transform: translateY(-2px);\n      box-shadow: 0 8px 22px rgba(255, 255, 255, 0.15);\n    }\n    .btn-refresh:active {\n      transform: translateY(0) scale(0.97);\n    }\n    .btn-refresh svg {\n      width: 14px;\n      height: 14px;\n      transition: transform 0.6s cubic-bezier(0.16, 1, 0.3, 1);\n    }\n    .btn-refresh.checking svg {\n      animation: spinRefresh 0.8s linear infinite;\n    }\n    @keyframes spinRefresh {\n      0% { transform: rotate(0deg); }\n      100% { transform: rotate(360deg); }\n    }\n\n    .btn-status-link {\n      background: transparent;\n      color: var(--text-sub);\n      border: 1px solid var(--border);\n      padding: 10px 22px;\n      border-radius: 24px;\n      font-size: 14px;\n      font-weight: 500;\n      text-decoration: none;\n      display: inline-flex;\n      align-items: center;\n      gap: 6px;\n      transition: color 0.15s ease, border-color 0.15s ease, transform 0.15s ease;\n    }\n    .btn-status-link:hover {\n      color: var(--text-title);\n      border-color: rgba(255, 255, 255, 0.25);\n      transform: translateY(-1px);\n    }\n    .btn-status-link svg {\n      width: 12px;\n      height: 12px;\n      transition: transform 0.2s ease;\n    }\n    .btn-status-link:hover svg {\n      transform: translateX(2px);\n    }\n\n    .btn-telegram-link {\n      background: rgba(42, 171, 238, 0.12);\n      color: #70c7f7;\n      border: 1px solid rgba(42, 171, 238, 0.35);\n      padding: 10px 20px;\n      border-radius: 24px;\n      font-size: 14px;\n      font-weight: 500;\n      text-decoration: none;\n      display: inline-flex;\n      align-items: center;\n      gap: 7px;\n      transition: all 0.2s cubic-bezier(0.16, 1, 0.3, 1);\n    }\n    .btn-telegram-link:hover {\n      background: rgba(42, 171, 238, 0.22);\n      color: #ffffff;\n      border-color: rgba(42, 171, 238, 0.65);\n      transform: translateY(-2px);\n      box-shadow: 0 6px 18px rgba(42, 171, 238, 0.25);\n    }\n    .btn-telegram-link:active {\n      transform: translateY(0) scale(0.97);\n    }\n    .btn-telegram-link svg {\n      width: 15px;\n      height: 15px;\n      fill: currentColor;\n      transition: transform 0.2s ease;\n    }\n    .btn-telegram-link:hover svg {\n      transform: scale(1.12) rotate(-8deg);\n    }\n\n    .btn-qr-link {\n      background: transparent;\n      color: var(--text-sub);\n      border: 1px solid var(--border);\n      padding: 10px 18px;\n      border-radius: 24px;\n      font-size: 14px;\n      font-weight: 500;\n      cursor: pointer;\n      text-decoration: none;\n      display: inline-flex;\n      align-items: center;\n      gap: 6px;\n      transition: color 0.15s ease, border-color 0.15s ease, transform 0.15s ease;\n    }\n    .btn-qr-link:hover {\n      color: var(--text-title);\n      border-color: rgba(255, 255, 255, 0.25);\n      transform: translateY(-1px);\n    }\n    .btn-qr-link svg {\n      width: 14px;\n      height: 14px;\n    }\n\n    .footer-telegram {\n      color: var(--text-sub);\n      text-decoration: none;\n      display: inline-flex;\n      align-items: center;\n      gap: 5px;\n      transition: color 0.15s ease;\n    }\n    .footer-telegram:hover {\n      color: #70c7f7;\n    }\n    .footer-telegram svg {\n      width: 13px;\n      height: 13px;\n      fill: currentColor;\n    }\n\n    /* Telegram QR Modal */\n    .modal-overlay {\n      position: fixed;\n      top: 0;\n      left: 0;\n      right: 0;\n      bottom: 0;\n      background: rgba(0, 0, 0, 0.82);\n      backdrop-filter: blur(8px);\n      -webkit-backdrop-filter: blur(8px);\n      display: flex;\n      align-items: center;\n      justify-content: center;\n      padding: 20px;\n      z-index: 1000;\n      opacity: 0;\n      visibility: hidden;\n      pointer-events: none;\n      transition: opacity 0.25s cubic-bezier(0.16, 1, 0.3, 1), visibility 0.25s;\n    }\n    .modal-overlay.active {\n      opacity: 1;\n      visibility: visible;\n      pointer-events: auto;\n    }\n    .modal-card {\n      background: #121212;\n      border: 1px solid rgba(255, 255, 255, 0.12);\n      border-radius: 22px;\n      padding: 24px 22px 20px;\n      max-width: 350px;\n      width: 100%;\n      text-align: center;\n      box-shadow: 0 30px 60px rgba(0, 0, 0, 0.75), 0 0 0 1px rgba(255, 255, 255, 0.05);\n      position: relative;\n      transform: scale(0.92) translateY(12px);\n      transition: transform 0.3s cubic-bezier(0.34, 1.4, 0.64, 1);\n    }\n    .modal-overlay.active .modal-card {\n      transform: scale(1) translateY(0);\n    }\n    .modal-close-btn {\n      position: absolute;\n      top: 14px;\n      right: 14px;\n      width: 28px;\n      height: 28px;\n      border-radius: 50%;\n      border: 1px solid var(--border);\n      background: rgba(255, 255, 255, 0.05);\n      color: var(--text-sub);\n      display: flex;\n      align-items: center;\n      justify-content: center;\n      cursor: pointer;\n      font-size: 16px;\n      line-height: 1;\n      transition: all 0.15s ease;\n    }\n    .modal-close-btn:hover {\n      color: #fff;\n      border-color: rgba(255, 255, 255, 0.3);\n      background: rgba(255, 255, 255, 0.1);\n    }\n    .modal-title {\n      font-size: 17px;\n      font-weight: 600;\n      color: var(--text-title);\n      margin-top: 4px;\n      margin-bottom: 6px;\n    }\n    .modal-desc {\n      font-size: 13px;\n      color: var(--text-sub);\n      line-height: 1.45;\n      margin-bottom: 16px;\n    }\n    .modal-qr-box {\n      background: #0a0a0a;\n      border-radius: 16px;\n      padding: 10px;\n      display: inline-block;\n      border: 1px solid rgba(255, 255, 255, 0.08);\n      margin-bottom: 14px;\n    }\n    .modal-qr-box img {\n      display: block;\n      width: 180px;\n      height: auto;\n      border-radius: 10px;\n      margin: 0 auto;\n    }\n    .modal-badge {\n      display: inline-flex;\n      align-items: center;\n      gap: 6px;\n      font-family: monospace;\n      font-size: 12px;\n      color: #70c7f7;\n      background: rgba(42, 171, 238, 0.1);\n      border: 1px solid rgba(42, 171, 238, 0.25);\n      padding: 4px 12px;\n      border-radius: 14px;\n      margin-bottom: 14px;\n    }\n    .modal-buttons {\n      display: flex;\n      flex-direction: column;\n      gap: 8px;\n    }\n    .btn-modal-open {\n      background: var(--button-bg);\n      color: var(--button-text);\n      font-weight: 600;\n      font-size: 13.5px;\n      padding: 10px 16px;\n      border-radius: 20px;\n      text-decoration: none;\n      display: inline-flex;\n      align-items: center;\n      justify-content: center;\n      gap: 6px;\n      transition: all 0.2s ease;\n    }\n    .btn-modal-open:hover {\n      background: var(--button-hover);\n      transform: translateY(-1px);\n    }\n    .btn-modal-app {\n      background: transparent;\n      color: var(--text-sub);\n      border: 1px solid var(--border);\n      font-size: 12.5px;\n      padding: 8px 14px;\n      border-radius: 20px;\n      text-decoration: none;\n      display: inline-flex;\n      align-items: center;\n      justify-content: center;\n      gap: 6px;\n      transition: all 0.15s ease;\n    }\n    .btn-modal-app:hover {\n      color: var(--text-title);\n      border-color: rgba(255, 255, 255, 0.25);\n    }\n\n    /* Live Countdown Progress Ring */\n    .auto-reload-card {\n      display: inline-flex;\n      align-items: center;\n      gap: 10px;\n      font-size: 12.5px;\n      color: var(--text-muted);\n      padding: 6px 14px;\n      background: rgba(255, 255, 255, 0.02);\n      border: 1px solid var(--border-subtle);\n      border-radius: 30px;\n      margin-bottom: 24px;\n      transition: border-color 0.2s;\n    }\n    .auto-reload-card:hover {\n      border-color: rgba(255, 255, 255, 0.12);\n    }\n    .countdown-ring-svg {\n      width: 18px;\n      height: 18px;\n      transform: rotate(-90deg);\n    }\n    .countdown-ring-bg {\n      fill: none;\n      stroke: rgba(255, 255, 255, 0.08);\n      stroke-width: 2.2;\n    }\n    .countdown-ring-fill {\n      fill: none;\n      stroke: #9ca3af;\n      stroke-width: 2.2;\n      stroke-linecap: round;\n      stroke-dasharray: 50.26;\n      stroke-dashoffset: 0;\n      transition: stroke-dashoffset 1s linear, stroke 0.3s;\n    }\n    .countdown-seconds-num {\n      color: var(--text-sub);\n      font-weight: 600;\n      font-variant-numeric: tabular-nums;\n    }\n\n    /* Expandable Maintenance Details Disclosure */\n    .details-toggle {\n      background: none;\n      border: none;\n      color: var(--text-muted);\n      font-size: 13px;\n      font-weight: 500;\n      cursor: pointer;\n      display: inline-flex;\n      align-items: center;\n      gap: 6px;\n      padding: 4px 10px;\n      border-radius: 6px;\n      transition: color 0.15s ease, background 0.15s ease;\n    }\n    .details-toggle:hover {\n      color: var(--text-sub);\n      background: rgba(255, 255, 255, 0.04);\n    }\n    .details-toggle svg {\n      width: 12px;\n      height: 12px;\n      transition: transform 0.3s cubic-bezier(0.16, 1, 0.3, 1);\n    }\n    .details-toggle.expanded svg {\n      transform: rotate(180deg);\n    }\n\n    .details-content-wrapper {\n      display: grid;\n      grid-template-rows: 0fr;\n      transition: grid-template-rows 0.35s cubic-bezier(0.16, 1, 0.3, 1);\n      width: 100%;\n      text-align: left;\n    }\n    .details-content-wrapper.open {\n      grid-template-rows: 1fr;\n    }\n    .details-inner {\n      overflow: hidden;\n    }\n    .details-card {\n      margin-top: 14px;\n      background: var(--card-bg);\n      border: 1px solid var(--border);\n      border-radius: 12px;\n      padding: 16px 20px;\n      font-size: 13px;\n      color: var(--text-sub);\n      display: flex;\n      flex-direction: column;\n      gap: 10px;\n      box-shadow: 0 8px 24px rgba(0, 0, 0, 0.3);\n    }\n    .details-item {\n      display: flex;\n      align-items: flex-start;\n      gap: 10px;\n    }\n    .details-check {\n      width: 16px;\n      height: 16px;\n      color: var(--emerald);\n      flex-shrink: 0;\n      margin-top: 1px;\n    }\n\n    /* Footer */\n    footer.bottom-bar {\n      font-size: 12.5px;\n      color: var(--text-muted);\n      display: flex;\n      align-items: center;\n      gap: 16px;\n      flex-wrap: wrap;\n      justify-content: center;\n      position: relative;\n      z-index: 10;\n    }\n    footer.bottom-bar a {\n      color: var(--text-muted);\n      text-decoration: none;\n      transition: color 0.15s ease;\n    }\n    footer.bottom-bar a:hover { color: var(--text-sub); }\n\n    /* Minimal Toast */\n    #minimal-toast {\n      position: fixed;\n      bottom: 28px;\n      left: 50%;\n      background: #181d27;\n      border: 1px solid rgba(255, 255, 255, 0.15);\n      color: #ffffff;\n      padding: 10px 18px;\n      border-radius: 20px;\n      font-size: 13px;\n      font-weight: 500;\n      box-shadow: 0 10px 30px rgba(0, 0, 0, 0.5);\n      transform: translate(-50%, 80px);\n      opacity: 0;\n      transition: all 0.3s cubic-bezier(0.34, 1.56, 0.64, 1);\n      z-index: 100;\n      display: flex;\n      align-items: center;\n      gap: 8px;\n      white-space: nowrap;\n      pointer-events: none;\n    }\n    #minimal-toast.show { transform: translate(-50%, 0); opacity: 1; }\n\n    @media (max-width: 520px) {\n      body { padding: 32px 20px 24px; }\n      main.center-box { width: 100%; margin: 24px auto; }\n      h1.heading { font-size: 24px; line-height: 1.3; }\n      p.body-text { font-size: 14px; line-height: 1.6; }\n      .button-group { flex-direction: column; width: 100%; gap: 10px; }\n      .btn-refresh, .btn-telegram-link, .btn-qr-link, .btn-status-link { width: 100%; justify-content: center; box-sizing: border-box; }\n      footer.bottom-bar { flex-direction: column; gap: 8px; font-size: 12px; }\n      .bottom-sep { display: none; }\n    }\n  </style>\n</head>\n<body>\n\n  <!-- Top Brand Navigation -->\n  <a href=\"#\" class=\"brand-link animate-entry delay-1\">\n    <div class=\"brand-symbol\">\n      <svg viewBox=\"0 0 24 24\"><path d=\"M20 2H4c-1.1 0-1.99.9-1.99 2L2 22l4-4h14c1.1 0 2-.9 2-2V4c0-1.1-.9-2-2-2zM6 9h12v2H6V9zm8 5H6v-2h8v2zm4-6H6V6h12v2z\"/></svg>\n    </div>\n    <span>Connecto</span>\n  </a>\n\n  <!-- Central Editorial Content -->\n  <main class=\"center-box\">\n    <!-- Kinetic Mechanical Clock Icon -->\n    <div class=\"clock-stage animate-entry delay-2\" title=\"Scheduled Maintenance Active\" onclick=\"handleClockClick()\">\n      <svg class=\"clock-svg\" viewBox=\"0 0 34 34\">\n        <circle class=\"clock-face\" cx=\"17\" cy=\"17\" r=\"14\"></circle>\n        <line class=\"clock-hand-hour\" id=\"hand-hour\" x1=\"17\" y1=\"17\" x2=\"17\" y2=\"10\"></line>\n        <line class=\"clock-hand-minute\" id=\"hand-minute\" x1=\"17\" y1=\"17\" x2=\"23\" y2=\"17\"></line>\n        <line class=\"clock-hand-second\" id=\"hand-second\" x1=\"17\" y1=\"17\" x2=\"17\" y2=\"7\"></line>\n        <circle class=\"clock-center-dot\" cx=\"17\" cy=\"17\" r=\"1.8\"></circle>\n      </svg>\n    </div>\n\n    <!-- Status Badge -->\n    <div class=\"status-badge animate-entry delay-3\">\n      <div class=\"status-dot-pulse\"></div>\n      <span>Routine Server Maintenance</span>\n    </div>\n\n    <!-- Main Editorial Headline -->\n    <h1 class=\"heading animate-entry delay-3\">\n      Temporarily down for maintenance\n    </h1>\n\n    <p class=\"body-text animate-entry delay-4\">\n      We are performing routine server upgrades to keep Connecto fast, secure, and reliable. We expect to be back online in just a few minutes. Thank you for your patience.\n    </p>\n\n    <!-- Primary Action Buttons -->\n    <div class=\"button-group animate-entry delay-5\">\n      <button class=\"btn-refresh\" id=\"btn-refresh\" onclick=\"handleRefresh()\">\n        <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><path d=\"M23 4v6h-6M1 20v-6h6\"/><path d=\"M3.51 9a9 9 0 0114.85-3.36L23 10M1 14l4.64 4.36A9 9 0 0020.49 15\"/></svg>\n        <span id=\"refresh-label\">Refresh Page</span>\n      </button>\n      <a href=\"https://t.me/VCONNECTOFUN\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"btn-telegram-link\" id=\"btn-telegram-primary\" onclick=\"handleTelegramClick(event)\">\n        <svg viewBox=\"0 0 24 24\"><path d=\"M12 2C6.48 2 2 6.48 2 12s4.48 10 10 10 10-4.48 10-10S17.52 2 12 2zm4.64 6.8c-.15 1.58-.8 5.42-1.13 7.19-.14.75-.42 1-.68 1.03-.58.05-1.02-.38-1.58-.75-.88-.58-1.38-.94-2.23-1.5-.99-.65-.35-1.01.22-1.59.15-.15 2.71-2.48 2.76-2.69a.2.2 0 00-.05-.18c-.06-.05-.14-.03-.21-.02-.09.02-1.49.95-4.22 2.79-.4.27-.76.41-1.08.4-.36-.01-1.04-.2-1.55-.37-.63-.2-1.12-.31-1.08-.66.02-.18.27-.36.75-.55 2.92-1.27 4.86-2.11 5.83-2.51 2.78-1.16 3.35-1.36 3.73-1.36.08 0 .27.02.39.12.1.08.13.19.14.27-.01.06.01.24 0 .38z\"/></svg>\n        <span>Telegram Updates</span>\n      </a>\n      <button type=\"button\" class=\"btn-qr-link\" onclick=\"openQrModal()\" title=\"View Channel QR Code\">\n        <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><rect x=\"3\" y=\"3\" width=\"7\" height=\"7\" rx=\"1.5\"></rect><rect x=\"14\" y=\"3\" width=\"7\" height=\"7\" rx=\"1.5\"></rect><rect x=\"14\" y=\"14\" width=\"7\" height=\"7\" rx=\"1.5\"></rect><rect x=\"3\" y=\"14\" width=\"7\" height=\"7\" rx=\"1.5\"></rect></svg>\n        <span>QR Code</span>\n      </button>\n      <a href=\"/static/status.html\" class=\"btn-status-link\">\n        <span>System Status</span>\n        <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><path d=\"M5 12h14M12 5l7 7-7 7\"/></svg>\n      </a>\n    </div>\n\n    <!-- Live Hairline Radial Countdown Tracker -->\n    <div class=\"auto-reload-card animate-entry delay-6\">\n      <svg class=\"countdown-ring-svg\">\n        <circle class=\"countdown-ring-bg\" cx=\"9\" cy=\"9\" r=\"8\"></circle>\n        <circle class=\"countdown-ring-fill\" id=\"countdown-ring\" cx=\"9\" cy=\"9\" r=\"8\"></circle>\n      </svg>\n      <span>Checking connection in <span class=\"countdown-seconds-num\" id=\"time-left\">30</span>s</span>\n    </div>\n\n    <!-- Expandable Clean Scope Disclosure -->\n    <div class=\"animate-entry delay-6\" style=\"width: 100%;\">\n      <button class=\"details-toggle\" id=\"details-toggle-btn\" onclick=\"toggleDetails()\">\n        <span>What's being updated?</span>\n        <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><path d=\"M6 9l6 6 6-6\"/></svg>\n      </button>\n\n      <div class=\"details-content-wrapper\" id=\"details-wrapper\">\n        <div class=\"details-inner\">\n          <div class=\"details-card\">\n            <div class=\"details-item\">\n              <svg class=\"details-check\" viewBox=\"0 0 20 20\" fill=\"currentColor\"><path fill-rule=\"evenodd\" d=\"M16.707 5.293a1 1 0 010 1.414l-8 8a1 1 0 01-1.414 0l-4-4a1 1 0 011.414-1.414L8 12.586l7.293-7.293a1 1 0 011.414 0z\" clip-rule=\"evenodd\"/></svg>\n              <span><strong>Database Optimization</strong>: Faster query caching and non-destructive index migrations.</span>\n            </div>\n            <div class=\"details-item\">\n              <svg class=\"details-check\" viewBox=\"0 0 20 20\" fill=\"currentColor\"><path fill-rule=\"evenodd\" d=\"M16.707 5.293a1 1 0 010 1.414l-8 8a1 1 0 01-1.414 0l-4-4a1 1 0 011.414-1.414L8 12.586l7.293-7.293a1 1 0 011.414 0z\" clip-rule=\"evenodd\"/></svg>\n              <span><strong>Real-Time Message Sync</strong>: Upgrading low-latency WebSocket connection gateways.</span>\n            </div>\n            <div class=\"details-item\">\n              <svg class=\"details-check\" viewBox=\"0 0 20 20\" fill=\"currentColor\"><path fill-rule=\"evenodd\" d=\"M16.707 5.293a1 1 0 010 1.414l-8 8a1 1 0 01-1.414 0l-4-4a1 1 0 011.414-1.414L8 12.586l7.293-7.293a1 1 0 011.414 0z\" clip-rule=\"evenodd\"/></svg>\n              <span><strong>100% Data Preservation</strong>: All messages, media, and channels remain safe and intact.</span>\n            </div>\n          </div>\n        </div>\n      </div>\n    </div>\n  </main>\n\n  <!-- Clean Bottom Footer -->\n  <footer class=\"bottom-bar animate-entry delay-6\">\n    <span>Need help? <a href=\"mailto:support@connecto.fun\">support@connecto.fun</a></span>\n    <span class=\"bottom-sep\">&bull;</span>\n    <a href=\"https://t.me/VCONNECTOFUN\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"footer-telegram\" onclick=\"handleTelegramClick(event)\">\n      <svg viewBox=\"0 0 24 24\"><path d=\"M12 2C6.48 2 2 6.48 2 12s4.48 10 10 10 10-4.48 10-10S17.52 2 12 2zm4.64 6.8c-.15 1.58-.8 5.42-1.13 7.19-.14.75-.42 1-.68 1.03-.58.05-1.02-.38-1.58-.75-.88-.58-1.38-.94-2.23-1.5-.99-.65-.35-1.01.22-1.59.15-.15 2.71-2.48 2.76-2.69a.2.2 0 00-.05-.18c-.06-.05-.14-.03-.21-.02-.09.02-1.49.95-4.22 2.79-.4.27-.76.41-1.08.4-.36-.01-1.04-.2-1.55-.37-.63-.2-1.12-.31-1.08-.66.02-.18.27-.36.75-.55 2.92-1.27 4.86-2.11 5.83-2.51 2.78-1.16 3.35-1.36 3.73-1.36.08 0 .27.02.39.12.1.08.13.19.14.27-.01.06.01.24 0 .38z\"/></svg>\n      <span>Telegram Updates (connecto-fun)</span>\n    </a>\n    <span class=\"bottom-sep\">&bull;</span>\n    <span>&copy; 2026 Connecto</span>\n  </footer>\n\n  <!-- Telegram QR Modal -->\n  <div id=\"telegram-modal\" class=\"modal-overlay\" onclick=\"closeQrModal(event)\">\n    <div class=\"modal-card\" onclick=\"event.stopPropagation()\">\n      <button type=\"button\" class=\"modal-close-btn\" onclick=\"closeQrModal()\" aria-label=\"Close modal\">&times;</button>\n      <h3 class=\"modal-title\">Official Telegram Updates</h3>\n      <p class=\"modal-desc\">Follow real-time maintenance logs, server ETA alerts, and instant announcements.</p>\n      \n      <div class=\"modal-qr-box\">\n        <img src=\"data:image/webp;base64,\" alt=\"Telegram Channel connecto-fun\" />\n      </div>\n\n      <div>\n        <div class=\"modal-badge\">\n          <span>\ud83d\udce2 connecto-fun</span>\n        </div>\n      </div>\n\n      <div class=\"modal-buttons\">\n        <a href=\"https://t.me/VCONNECTOFUN\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"btn-modal-open\" onclick=\"handleTelegramClick(event)\">\n          <span>Open Telegram Channel</span>\n          <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\" width=\"14\" height=\"14\"><path d=\"M5 12h14M12 5l7 7-7 7\"/></svg>\n        </a>\n        <a href=\"tg://resolve?domain=VCONNECTOFUN\" class=\"btn-modal-app\" onclick=\"showToast('\u26a1 Connecting in Telegram App...')\">\n          <span>Connect in Telegram App</span>\n        </a>\n      </div>\n    </div>\n  </div>\n\n  <!-- Minimal Spring Toast -->\n  <div id=\"minimal-toast\">\n    <svg width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><circle cx=\"12\" cy=\"12\" r=\"10\"></circle><polyline points=\"12 6 12 12 14 14\"></polyline></svg>\n    <span id=\"toast-text\"></span>\n  </div>\n\n  <script>\n    const TOTAL_SECONDS = 30;\n    let remaining = TOTAL_SECONDS;\n    const timeLeft = document.getElementById('time-left');\n    const ringFill = document.getElementById('countdown-ring');\n    const toast = document.getElementById('minimal-toast');\n    const toastText = document.getElementById('toast-text');\n    const refreshBtn = document.getElementById('btn-refresh');\n    const refreshLabel = document.getElementById('refresh-label');\n    const detailsWrapper = document.getElementById('details-wrapper');\n    const detailsToggleBtn = document.getElementById('details-toggle-btn');\n\n    const ringCircumference = 2 * Math.PI * 8; // 50.265\n\n    function updateCountdownVisual() {\n      timeLeft.innerText = remaining;\n      const offset = ringCircumference - (remaining / TOTAL_SECONDS) * ringCircumference;\n      ringFill.style.strokeDashoffset = offset;\n    }\n\n    const timerInterval = setInterval(() => {\n      remaining--;\n      if (remaining <= 0) {\n        remaining = TOTAL_SECONDS;\n        handleRefresh(true);\n      }\n      updateCountdownVisual();\n    }, 1000);\n\n    function handleRefresh(silent = false) {\n      refreshBtn.classList.add('checking');\n      if (!silent) refreshLabel.innerText = 'Checking...';\n\n      fetch('/api/v1/health', { method: 'GET', cache: 'no-store' })\n        .then(res => {\n          refreshBtn.classList.remove('checking');\n          if (res.status === 200) {\n            showToast('\ud83c\udf89 Connecto is back online! Refreshing...');\n            setTimeout(() => window.location.reload(), 900);\n          } else {\n            if (!silent) showToast('Maintenance is still ongoing. Re-checking shortly.');\n            refreshLabel.innerText = 'Refresh Page';\n            remaining = TOTAL_SECONDS;\n            updateCountdownVisual();\n          }\n        })\n        .catch(() => {\n          refreshBtn.classList.remove('checking');\n          if (!silent) showToast('Maintenance is still ongoing. Re-checking shortly.');\n          refreshLabel.innerText = 'Refresh Page';\n          remaining = TOTAL_SECONDS;\n          updateCountdownVisual();\n        });\n    }\n\n    function toggleDetails() {\n      const isOpen = detailsWrapper.classList.contains('open');\n      if (isOpen) {\n        detailsWrapper.classList.remove('open');\n        detailsToggleBtn.classList.remove('expanded');\n      } else {\n        detailsWrapper.classList.add('open');\n        detailsToggleBtn.classList.add('expanded');\n      }\n    }\n\n    function handleClockClick() {\n      // Playful quick spin on clock hands when tapped\n      const handSec = document.getElementById('hand-second');\n      const handMin = document.getElementById('hand-minute');\n      handSec.style.animation = 'rotateSecond 0.8s ease-in-out 1';\n      handMin.style.animation = 'rotateMinute 1.5s ease-in-out 1';\n      setTimeout(() => {\n        handSec.style.animation = 'rotateSecond 4s linear infinite';\n        handMin.style.animation = 'rotateMinute 12s linear infinite';\n      }, 1600);\n      showToast('\u26a1 Precision server synchronizers active.');\n    }\n\n    function showToast(msg) {\n      toastText.innerText = msg;\n      toast.classList.add('show');\n      setTimeout(() => toast.classList.remove('show'), 3500);\n    }\n\n    function handleTelegramClick(e) {\n      showToast('\u2708\ufe0f Opening connecto-fun on Telegram...');\n    }\n\n    function openQrModal() {\n      const modal = document.getElementById('telegram-modal');\n      if (modal) modal.classList.add('active');\n    }\n\n    function closeQrModal(e) {\n      const modal = document.getElementById('telegram-modal');\n      if (modal) modal.classList.remove('active');\n    }\n\n    document.addEventListener('keydown', (e) => {\n      if (e.key === 'Escape') closeQrModal();\n    });\n\n    if (window.location.hash === '#qr' || window.location.hash === '#telegram') {\n      setTimeout(openQrModal, 400);\n    }\n  </script>\n</body>\n</html>\n";

const NEWS_HTML = "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0, maximum-scale=1.0, user-scalable=no\">\n  <title>Newsroom Maintenance \u2014 news.connecto.fun</title>\n  <link rel=\"icon\" type=\"image/svg+xml\" href=\"data:image/svg+xml,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 100 100'><rect width='100' height='100' rx='20' fill='%23DC2626'/><text x='50%' y='68%' font-family='sans-serif' font-weight='900' font-size='55' fill='%23FFFFFF' text-anchor='middle'>NEWS</text></svg>\">\n  <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\"><link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin><link href=\"https://fonts.googleapis.com/css2?family=Cinzel:wght@700;900&family=Plus+Jakarta+Sans:wght@400;500;600;700;800&family=JetBrains+Mono:wght@500;700&display=swap\" rel=\"stylesheet\">\n  <style>\n    :root{--bg-dark:#090D16;--card-bg:rgba(15,23,42,0.85);--red-news:#EF4444;--red-glow:rgba(239,68,68,0.35);--gold-accent:#F59E0B;--text-white:#F8FAFC;--text-muted:#94A3B8;--border-subtle:rgba(255,255,255,0.1)}\n    *{box-sizing:border-box;margin:0;padding:0}\n    body{background-color:var(--bg-dark);background-image:radial-gradient(circle at 50% 10%,rgba(239,68,68,0.12) 0%,transparent 50%),radial-gradient(circle at 15% 90%,rgba(59,130,246,0.08) 0%,transparent 40%),radial-gradient(circle at 85% 90%,rgba(245,158,11,0.08) 0%,transparent 40%);color:var(--text-white);font-family:'Plus Jakarta Sans',-apple-system,BlinkMacSystemFont,sans-serif;min-height:100vh;display:flex;flex-direction:column;justify-content:space-between;overflow-x:hidden;position:relative}\n    .ticker-bar{width:100%;background:linear-gradient(90deg,#991B1B 0%,#DC2626 50%,#991B1B 100%);color:#FFFFFF;padding:8px 16px;display:flex;align-items:center;font-size:13px;font-weight:700;overflow:hidden;box-shadow:0 4px 15px rgba(220,38,38,0.3);z-index:30}\n    .ticker-badge{background:#FFFFFF;color:#DC2626;padding:3px 8px;border-radius:4px;font-size:11px;font-weight:900;margin-right:14px;white-space:nowrap;display:flex;align-items:center;gap:6px}\n    .ticker-dot{width:6px;height:6px;background:#DC2626;border-radius:50%;animation:pulse 1s infinite}\n    @keyframes pulse{0%,100%{opacity:1}50%{opacity:0.3}}\n    .ticker-text{white-space:nowrap;animation:scrollTicker 25s linear infinite}\n    @keyframes scrollTicker{0%{transform:translateX(100%)}100%{transform:translateX(-100%)}}\n    main.news-container{flex:1;width:100%;max-width:1000px;margin:0 auto;padding:40px 24px;display:flex;flex-direction:column;align-items:center;text-align:center;z-index:10}\n    .newspaper-masthead{border-bottom:2px solid var(--border-subtle);border-top:2px solid var(--border-subtle);padding:12px 20px;width:100%;max-width:680px;margin-bottom:28px;display:flex;align-items:center;justify-content:space-between;color:var(--text-muted);font-size:12px;text-transform:uppercase;letter-spacing:1.5px;font-family:'JetBrains Mono',monospace}\n    .masthead-title{font-family:'Cinzel',serif;font-size:38px;font-weight:900;letter-spacing:3px;color:#FFFFFF;text-shadow:0 2px 10px rgba(0,0,0,0.5);margin-bottom:6px}\n    .masthead-tagline{font-size:13.5px;color:var(--gold-accent);font-weight:600;letter-spacing:1px;margin-bottom:24px}\n    .satellite-wrap{position:relative;width:130px;height:130px;margin:0 auto 24px auto;display:flex;align-items:center;justify-content:center}\n    .pulse-ring{position:absolute;width:100%;height:100%;border-radius:50%;border:2px solid var(--red-news);opacity:0;animation:radarPulse 3s cubic-bezier(0.215,0.61,0.355,1) infinite}\n    .ring-2{animation-delay:1s}.ring-3{animation-delay:2s}\n    @keyframes radarPulse{0%{transform:scale(0.3);opacity:0.8}100%{transform:scale(1.4);opacity:0}}\n    .satellite-center-icon{width:68px;height:68px;background:linear-gradient(135deg,#DC2626 0%,#991B1B 100%);border-radius:50%;display:flex;align-items:center;justify-content:center;box-shadow:0 0 30px var(--red-glow);z-index:5}\n    .satellite-center-icon svg{width:34px;height:34px;fill:#FFFFFF}\n    .news-headline{font-family:'Cinzel',serif;font-size:30px;font-weight:700;color:#FFFFFF;margin-bottom:14px;line-height:1.3}\n    .news-headline span.red-highlight{color:var(--red-news);border-bottom:2px solid var(--red-news)}\n    .news-lead-text{font-size:16px;color:var(--text-muted);line-height:1.65;max-width:640px;margin-bottom:30px}\n    .news-status-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:16px;width:100%;max-width:680px;margin-bottom:32px}\n    .status-news-card{background:var(--card-bg);border:1px solid var(--border-subtle);border-radius:14px;padding:16px 12px;text-align:center;backdrop-filter:blur(16px);box-shadow:0 8px 24px rgba(0,0,0,0.3)}\n    .status-news-card .card-metric{font-size:12px;font-family:'JetBrains Mono',monospace;color:var(--text-muted);margin-bottom:6px;text-transform:uppercase}\n    .status-news-card .card-val{font-size:14px;font-weight:700;color:#FFFFFF;display:flex;align-items:center;justify-content:center;gap:6px}\n    .status-indicator-dot{width:7px;height:7px;border-radius:50%}\n    .dot-green{background:#10B981;box-shadow:0 0 8px #10B981}.dot-yellow{background:#F59E0B;box-shadow:0 0 8px #F59E0B}.dot-blue{background:#3B82F6;box-shadow:0 0 8px #3B82F6}\n    .reconnect-wire-btn{display:inline-flex;align-items:center;gap:10px;background:linear-gradient(135deg,#DC2626 0%,#B91C1C 100%);color:#FFFFFF;border:none;padding:12px 28px;border-radius:30px;font-size:14px;font-weight:700;cursor:pointer;box-shadow:0 4px 20px var(--red-glow);transition:all 0.25s ease;margin-bottom:24px}\n    .reconnect-wire-btn:hover{transform:translateY(-2px);box-shadow:0 6px 26px rgba(239,68,68,0.5)}\n    .wire-socials{display:flex;align-items:center;gap:14px}\n    .wire-btn{width:40px;height:40px;border-radius:50%;background:rgba(255,255,255,0.05);border:1px solid var(--border-subtle);display:flex;align-items:center;justify-content:center;color:var(--text-muted);text-decoration:none;transition:all 0.2s ease}\n    .wire-btn:hover{background:var(--red-news);color:#FFFFFF;transform:translateY(-2px)}\n    .wire-btn svg{width:18px;height:18px;fill:currentColor}\n    footer.news-footer{width:100%;border-top:1px solid var(--border-subtle);padding:16px 24px;display:flex;align-items:center;justify-content:space-between;font-size:12.5px;color:var(--text-muted);background:rgba(10,15,28,0.95)}\n    .badge-status{background:rgba(239,68,68,0.15);color:#F87171;border:1px solid rgba(239,68,68,0.3);padding:3px 8px;border-radius:4px;font-family:'JetBrains Mono',monospace;font-size:11px}\n    @media(max-width:680px){.masthead-title{font-size:28px}.news-headline{font-size:22px}.news-status-grid{grid-template-columns:1fr}footer.news-footer{flex-direction:column;gap:8px;text-align:center}}\n  </style>\n</head>\n<body>\n  <div class=\"ticker-bar\"><div class=\"ticker-badge\"><span class=\"ticker-dot\"></span><span>PRESS WIRE</span></div><div class=\"ticker-text\">LIVE BROADCAST: Platform Newsroom infrastructure upgrading \u2022 Publishing pipeline & real-time telemetry syncing \u2022 Check back shortly for breaking dispatches \u2022</div></div>\n  <main class=\"news-container\">\n    <div class=\"newspaper-masthead\"><span>EDITION: GLOBAL WIRE</span><span>CONNECTO MEDIA NETWORK</span><span>STATUS: SYNCHRONIZING</span></div>\n    <h1 class=\"masthead-title\">THE CHRONICLE</h1>\n    <div class=\"masthead-tagline\">LIVE BROADCAST & EDITORIAL WIRE // news.connecto.fun</div>\n    <div class=\"satellite-wrap\"><div class=\"pulse-ring\"></div><div class=\"pulse-ring ring-2\"></div><div class=\"pulse-ring ring-3\"></div><div class=\"satellite-center-icon\"><svg viewBox=\"0 0 24 24\"><path d=\"M12 2C6.48 2 2 6.48 2 12s4.48 10 10 10 10-4.48 10-10S17.52 2 12 2zm-1 17.93c-3.95-.49-7-3.85-7-7.93 0-.62.08-1.21.21-1.79L9 15v1c0 1.1.9 2 2 2v1.93zm6.9-2.54c-.26-.81-1-1.39-1.9-1.39h-1v-3c0-.55-.45-1-1-1H8v-2h2c.55 0 1-.45 1-1V7h2c1.1 0 2-.9 2-2v-.41c2.93 1.19 5 4.06 5 7.41 0 2.08-.8 3.97-2.1 5.39z\"/></svg></div></div>\n    <h2 class=\"news-headline\">Newsroom Publishing Engine <span class=\"red-highlight\">Under Maintenance</span></h2>\n    <p class=\"news-lead-text\">Our editorial desk, real-time live tickers, and media content distribution networks are currently receiving scheduled system upgrades. Full wire broadcasting resumes in a moment.</p>\n    <div class=\"news-status-grid\">\n      <div class=\"status-news-card\"><div class=\"card-metric\">WIRE TELEMETRY</div><div class=\"card-val\"><span class=\"status-indicator-dot dot-yellow\"></span> Upgrading</div></div>\n      <div class=\"status-news-card\"><div class=\"card-metric\">MEDIA CLUSTER</div><div class=\"card-val\"><span class=\"status-indicator-dot dot-blue\"></span> Syncing</div></div>\n      <div class=\"status-news-card\"><div class=\"card-metric\">AUTO-RELOAD</div><div class=\"card-val\"><span class=\"status-indicator-dot dot-green\"></span> <span id=\"countdown-wire\">30</span>s</div></div>\n    </div>\n    <button class=\"reconnect-wire-btn\" onclick=\"checkWireStatus()\"><svg width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M12 4V1L8 5l4 4V6c3.31 0 6 2.69 6 6 0 1.01-.25 1.97-.7 2.8l1.46 1.46A7.93 7.93 0 0020 12c0-4.42-3.58-8-8-8zm0 14c-3.31 0-6-2.69-6-6 0-1.01.25-1.97.7-2.8L5.24 7.74A7.93 7.93 0 004 12c0 4.42 3.58 8 8 8v3l4-4-4-4v3z\"/></svg><span>Check Live Wire Now</span></button>\n    <div class=\"wire-socials\">\n      <a href=\"https://t.me/connecto\" target=\"_blank\" rel=\"noopener\" class=\"wire-btn\" title=\"Telegram News Wire\"><svg viewBox=\"0 0 24 24\"><path d=\"M12 2C6.48 2 2 6.48 2 12s4.48 10 10 10 10-4.48 10-10S17.52 2 12 2zm4.64 6.8c-.15 1.58-.8 5.42-1.13 7.19-.14.75-.42 1-.68 1.03-.58.05-1.02-.38-1.58-.75-.88-.58-1.38-.94-2.23-1.5-.99-.65-.35-1.01.22-1.59.15-.15 2.71-2.48 2.76-2.69a.2.2 0 00-.05-.18c-.06-.05-.14-.03-.21-.02-.09.02-1.49.95-4.22 2.79-.4.27-.76.41-1.08.4-.36-.01-1.04-.2-1.55-.37-.63-.2-1.12-.31-1.08-.66.02-.18.27-.36.75-.55 2.92-1.27 4.86-2.11 5.83-2.51 2.78-1.16 3.35-1.36 3.73-1.36.08 0 .27.02.39.12.1.08.13.19.14.27-.01.06.01.24 0 .38z\"/></svg></a>\n      <a href=\"mailto:press@connecto.fun\" class=\"wire-btn\" title=\"Press Room Email\"><svg viewBox=\"0 0 24 24\"><path d=\"M20 4H4c-1.1 0-1.99.9-1.99 2L2 18c0 1.1.9 2 2 2h16c1.1 0 2-.9 2-2V6c0-1.1-.9-2-2-2zm0 4l-8 5-8-5V6l8 5 8-5v2z\"/></svg></a>\n    </div>\n  </main>\n  <footer class=\"news-footer\"><div>\u00a9 2026 <strong>news.connecto.fun</strong> \u2022 All rights reserved.</div><div>Live Dispatch Status: <span class=\"badge-status\">HTTP 503 \u2022 Standby</span></div></footer>\n  </body>\n</html>";

const RESINORA_HTML = "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0, maximum-scale=1.0, user-scalable=no\">\n  <title>Curating Our Next Collection \u2014 Resinora Atelier</title>\n  <link rel=\"icon\" type=\"image/svg+xml\" href=\"data:image/svg+xml,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 100 100'><rect width='100' height='100' rx='25' fill='%23131118'/><text x='50%' y='68%' font-family='serif' font-weight='bold' font-size='55' fill='%23E0A96D' text-anchor='middle'>R</text></svg>\">\n  <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\"><link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin><link href=\"https://fonts.googleapis.com/css2?family=Cormorant+Garamond:ital,wght@0,500;0,600;0,700;1,400;1,600&family=Plus+Jakarta+Sans:wght@300;400;500;600;700&display=swap\" rel=\"stylesheet\">\n  <style>\n    :root{--bg-dark:#0D0B10;--bg-card:rgba(22,18,28,0.75);--gold-primary:#E0A96D;--gold-light:#F7D4A8;--gold-gradient:linear-gradient(135deg,#F7D4A8 0%,#E0A96D 50%,#B87D4B 100%);--text-white:#FAF6F0;--text-muted:#A39BA8;--border-gold:rgba(224,169,109,0.22);--border-subtle:rgba(255,255,255,0.08)}\n    *{box-sizing:border-box;margin:0;padding:0}\n    body{background-color:var(--bg-dark);background-image:radial-gradient(circle at 50% 0%,rgba(224,169,109,0.12) 0%,transparent 60%),radial-gradient(circle at 10% 90%,rgba(212,123,133,0.08) 0%,transparent 40%),radial-gradient(circle at 90% 80%,rgba(184,125,75,0.08) 0%,transparent 40%);color:var(--text-white);font-family:'Plus Jakarta Sans',-apple-system,BlinkMacSystemFont,sans-serif;min-height:100vh;display:flex;flex-direction:column;justify-content:space-between;overflow-x:hidden;position:relative}\n    .atelier-announcement{width:100%;background:linear-gradient(90deg,rgba(224,169,109,0.1) 0%,rgba(212,123,133,0.15) 50%,rgba(224,169,109,0.1) 100%);border-bottom:1px solid var(--border-gold);padding:10px 20px;text-align:center;font-size:12.5px;letter-spacing:1.5px;text-transform:uppercase;color:var(--gold-light);font-weight:600;z-index:20}\n    main.atelier-container{flex:1;width:100%;max-width:860px;margin:0 auto;padding:48px 24px;display:flex;flex-direction:column;align-items:center;text-align:center;z-index:10}\n    .brand-section{margin-bottom:32px;display:flex;flex-direction:column;align-items:center;gap:12px}\n    .monogram-badge{width:58px;height:58px;border-radius:50%;border:1px solid var(--border-gold);background:rgba(224,169,109,0.06);display:flex;align-items:center;justify-content:center;box-shadow:0 0 25px rgba(224,169,109,0.15)}\n    .monogram-badge svg{width:28px;height:28px;fill:var(--gold-primary)}\n    .brand-title{font-family:'Cormorant Garamond',Georgia,serif;font-size:42px;font-weight:700;letter-spacing:4px;text-transform:uppercase;background:var(--gold-gradient);-webkit-background-clip:text;-webkit-text-fill-color:transparent}\n    .brand-subtitle{font-size:13px;color:var(--text-muted);letter-spacing:3px;text-transform:uppercase;font-weight:500}\n    .artisan-gem-wrap{position:relative;width:140px;height:140px;margin:0 auto 28px auto;display:flex;align-items:center;justify-content:center}\n    .gem-glow{position:absolute;width:100%;height:100%;border-radius:50%;background:radial-gradient(circle,rgba(224,169,109,0.25) 0%,transparent 70%);animation:breathe 4s ease-in-out infinite alternate}\n    @keyframes breathe{0%{transform:scale(0.85);opacity:0.4}100%{transform:scale(1.15);opacity:0.9}}\n    .gem-svg{width:100px;height:100px;filter:drop-shadow(0 10px 20px rgba(0,0,0,0.5));animation:floatGem 6s ease-in-out infinite}\n    @keyframes floatGem{0%,100%{transform:translateY(0px) rotate(0deg)}50%{transform:translateY(-8px) rotate(2deg)}}\n    h1.heading{font-family:'Cormorant Garamond',Georgia,serif;font-size:38px;font-weight:600;line-height:1.25;color:var(--text-white);margin-bottom:16px;max-width:680px}\n    h1.heading span.italic-gold{font-style:italic;color:var(--gold-light)}\n    p.lead-copy{font-size:15.5px;line-height:1.7;color:var(--text-muted);max-width:620px;margin-bottom:36px}\n    .atelier-cards-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:16px;width:100%;max-width:760px;margin-bottom:36px}\n    .atelier-card{background:var(--bg-card);border:1px solid var(--border-gold);border-radius:18px;padding:22px 18px;text-align:center;backdrop-filter:blur(20px);box-shadow:0 12px 30px rgba(0,0,0,0.35);transition:transform 0.3s ease,border-color 0.3s ease}\n    .atelier-card:hover{transform:translateY(-3px);border-color:rgba(224,169,109,0.5)}\n    .card-icon{font-size:24px;margin-bottom:10px;display:inline-block}\n    .card-title{font-size:13.5px;font-weight:700;color:var(--gold-light);margin-bottom:6px}\n    .card-desc{font-size:12.5px;color:var(--text-muted);line-height:1.5}\n    .action-row{display:flex;align-items:center;justify-content:center;gap:16px;flex-wrap:wrap;margin-bottom:36px}\n    .btn-gold{display:inline-flex;align-items:center;gap:10px;background:var(--gold-gradient);color:#131118;font-weight:700;font-size:14px;padding:14px 28px;border-radius:30px;text-decoration:none;box-shadow:0 8px 24px rgba(224,169,109,0.25);transition:all 0.25s ease;border:none;cursor:pointer}\n    .btn-gold:hover{transform:translateY(-2px);box-shadow:0 12px 30px rgba(224,169,109,0.4)}\n    .btn-outline{display:inline-flex;align-items:center;gap:8px;background:rgba(255,255,255,0.04);color:var(--gold-light);border:1px solid var(--border-gold);font-size:14px;font-weight:600;padding:14px 26px;border-radius:30px;text-decoration:none;transition:all 0.25s ease;cursor:pointer}\n    .btn-outline:hover{background:rgba(224,169,109,0.1);border-color:var(--gold-primary);transform:translateY(-2px)}\n    .vip-subscribe{width:100%;max-width:480px;background:rgba(22,18,28,0.6);border:1px solid var(--border-subtle);border-radius:40px;padding:6px 6px 6px 20px;display:flex;align-items:center;margin-bottom:30px}\n    .vip-input{flex:1;background:transparent;border:none;color:#FFF;font-size:13.5px;outline:none;font-family:inherit}\n    .vip-input::placeholder{color:rgba(163,155,168,0.7)}\n    .vip-submit{background:var(--gold-primary);color:#131118;border:none;padding:10px 20px;border-radius:30px;font-size:12.5px;font-weight:700;cursor:pointer;transition:background 0.2s}\n    .vip-submit:hover{background:var(--gold-light)}\n    footer.atelier-footer{width:100%;border-top:1px solid var(--border-subtle);padding:20px 32px;display:flex;align-items:center;justify-content:space-between;font-size:12.5px;color:var(--text-muted);background:rgba(10,8,14,0.95);z-index:20}\n    .atelier-status-pill{display:inline-flex;align-items:center;gap:6px;background:rgba(224,169,109,0.1);border:1px solid var(--border-gold);color:var(--gold-light);padding:4px 10px;border-radius:20px;font-size:11px;font-weight:600}\n    .status-spark{width:6px;height:6px;background:var(--gold-primary);border-radius:50%;box-shadow:0 0 8px var(--gold-primary)}\n    @media(max-width:768px){.brand-title{font-size:32px}h1.heading{font-size:28px}.atelier-cards-grid{grid-template-columns:1fr}.action-row{flex-direction:column;width:100%}.btn-gold,.btn-outline{width:100%;justify-content:center}footer.atelier-footer{flex-direction:column;gap:12px;text-align:center}}\n  </style>\n</head>\n<body>\n  <div class=\"atelier-announcement\">\u2728 Resinora Studio & Atelier \u2022 Private Catalog Restocking & Collection Curation</div>\n  <main class=\"atelier-container\">\n    <div class=\"brand-section\">\n      <div class=\"monogram-badge\"><svg viewBox=\"0 0 24 24\"><path d=\"M12 2L3 9l9 13 9-13-9-7zm0 3.5L18.2 9 12 18.2 5.8 9 12 5.5z\"/></svg></div>\n      <div class=\"brand-title\">RESINORA</div>\n      <div class=\"brand-subtitle\">Fine Handcrafted Resin & Botanical Atelier // resinora.connecto.fun</div>\n    </div>\n    <div class=\"artisan-gem-wrap\">\n      <div class=\"gem-glow\"></div>\n      <svg class=\"gem-svg\" viewBox=\"0 0 100 100\" fill=\"none\" xmlns=\"http://www.w3.org/2000/svg\">\n        <defs><linearGradient id=\"gemGrad\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"100%\"><stop offset=\"0%\" stop-color=\"#F7D4A8\" stop-opacity=\"0.9\"/><stop offset=\"50%\" stop-color=\"#E0A96D\" stop-opacity=\"0.75\"/><stop offset=\"100%\" stop-color=\"#8E4A49\" stop-opacity=\"0.85\"/></linearGradient><linearGradient id=\"goldLeaf\" x1=\"0%\" y1=\"100%\" x2=\"100%\" y2=\"0%\"><stop offset=\"0%\" stop-color=\"#FFEBB5\"/><stop offset=\"100%\" stop-color=\"#D4AF37\"/></linearGradient></defs>\n        <polygon points=\"50,6 88,34 72,92 28,92 12,34\" fill=\"url(#gemGrad)\" stroke=\"#F7D4A8\" stroke-width=\"1.5\"/>\n        <polygon points=\"50,6 50,48 12,34\" fill=\"#FFFFFF\" fill-opacity=\"0.2\"/>\n        <polygon points=\"50,6 88,34 50,48\" fill=\"#E0A96D\" fill-opacity=\"0.3\"/>\n        <polygon points=\"50,48 88,34 72,92\" fill=\"#8E4A49\" fill-opacity=\"0.35\"/>\n        <polygon points=\"50,48 72,92 28,92\" fill=\"#D47B85\" fill-opacity=\"0.25\"/>\n        <polygon points=\"50,48 28,92 12,34\" fill=\"#FAF6F0\" fill-opacity=\"0.15\"/>\n        <path d=\"M50 78 C48 65, 42 55, 36 45 C44 46, 52 52, 50 78 Z\" fill=\"url(#goldLeaf)\" fill-opacity=\"0.85\"/>\n        <path d=\"M50 68 C52 58, 58 50, 64 42 C56 44, 48 50, 50 68 Z\" fill=\"url(#goldLeaf)\" fill-opacity=\"0.9\"/>\n        <circle cx=\"42\" cy=\"30\" r=\"1.5\" fill=\"#FFEBB5\"/><circle cx=\"60\" cy=\"36\" r=\"2\" fill=\"#FFEBB5\"/><circle cx=\"34\" cy=\"62\" r=\"1.8\" fill=\"#FFEBB5\"/><circle cx=\"58\" cy=\"74\" r=\"1.2\" fill=\"#FFEBB5\"/>\n      </svg>\n    </div>\n    <h1 class=\"heading\">Curating Our Next <span class=\"italic-gold\">Bespoke Collection</span></h1>\n    <p class=\"lead-copy\">Our online boutique is temporarily paused while our studio artisans curate limited-edition botanical resin slabs, handcrafted jewelry, and custom preservation art.</p>\n    <div class=\"atelier-cards-grid\">\n      <div class=\"atelier-card\"><div class=\"card-icon\">\ud83d\udce6</div><div class=\"card-title\">Existing Orders Safe</div><div class=\"card-desc\">All commissioned pieces and custom bridal preservations are being fulfilled on schedule.</div></div>\n      <div class=\"atelier-card\"><div class=\"card-icon\">\ud83c\udf3f</div><div class=\"card-title\">Botanical Drop</div><div class=\"card-desc\">New 24K Gold Flora and Preserved Fern tabletop collections launching shortly.</div></div>\n      <div class=\"atelier-card\"><div class=\"card-icon\">\ud83d\udc8e</div><div class=\"card-title\">VIP Concierge</div><div class=\"card-desc\">Urgent custom quotes and bridal bookings remain open via our VIP direct line.</div></div>\n    </div>\n    <div class=\"action-row\">\n      <a href=\"https://wa.me/?text=Hello%20Resinora%20Team%2C%20I%20would%20like%20to%20inquire%20about%20a%20custom%20resin%20piece\" target=\"_blank\" rel=\"noopener\" class=\"btn-gold\"><svg width=\"18\" height=\"18\" viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M12.04 2c-5.46 0-9.91 4.45-9.91 9.91 0 1.75.46 3.45 1.32 4.95L2.05 22l5.25-1.38c1.45.79 3.08 1.21 4.74 1.21 5.46 0 9.91-4.45 9.91-9.91 0-2.65-1.03-5.14-2.9-7.01A9.816 9.816 0 0 0 12.04 2m.01 1.67c2.2 0 4.26.86 5.82 2.42a8.225 8.225 0 0 1 2.41 5.83c0 4.54-3.7 8.24-8.24 8.24-1.48 0-2.93-.4-4.2-1.15l-.3-.18-3.12.82.83-3.04-.2-.31a8.196 8.196 0 0 1-1.26-4.38c0-4.54 3.7-8.24 8.24-8.24m4.52 11.66c-.25-.13-1.47-.72-1.7-.81-.23-.08-.39-.13-.56.13-.17.25-.64.81-.79.97-.14.17-.29.19-.54.06-.25-.13-1.06-.39-2.03-1.25-.75-.67-1.26-1.5-1.41-1.75-.14-.25-.02-.39.11-.51.11-.11.25-.29.37-.44.13-.15.17-.25.25-.42.08-.17.04-.31-.02-.44-.06-.13-.56-1.35-.77-1.85-.2-.49-.41-.42-.56-.43h-.48c-.17 0-.44.06-.67.31-.23.25-.88.86-.88 2.1 0 1.24.9 2.44 1.03 2.61.13.17 1.78 2.72 4.31 3.81.6.26 1.07.41 1.44.53.61.19 1.16.17 1.6.1.49-.07 1.47-.6 1.68-1.18.21-.58.21-1.07.15-1.18-.06-.1-.23-.17-.48-.29\"/></svg><span>Message Atelier Concierge</span></a>\n      <button class=\"btn-outline\" onclick=\"checkStoreStatus()\"><svg width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><path d=\"M23 4v6h-6M1 20v-6h6\"/><path d=\"M3.51 9a9 9 0 0114.85-3.36L23 10M1 14l4.64 4.36A9 9 0 0020.49 15\"/></svg><span id=\"store-refresh-text\">Check Store Status (<span id=\"store-timer\">30</span>s)</span></button>\n    </div>\n    <form class=\"vip-subscribe\" onsubmit=\"event.preventDefault(); alert('\u2728 Thank you! You have been granted VIP Early Access for our next collection drop.');\">\n      <input type=\"email\" class=\"vip-input\" placeholder=\"Enter email for 15-min VIP early drop access...\" required>\n      <button type=\"submit\" class=\"vip-submit\">Join VIP List</button>\n    </form>\n  </main>\n  <footer class=\"atelier-footer\"><div>\u00a9 2026 <strong>Resinora Studio & Atelier</strong> \u2022 All rights reserved.</div><div>Boutique Status: <span class=\"atelier-status-pill\"><span class=\"status-spark\"></span> Curating Drops</span></div></footer>\n  </body>\n</html>";

export default {
  async fetch(request, env, ctx) {
    const url = new URL(request.url);
    const host = url.hostname.toLowerCase();

    // Pass-through for origin health probes if origin comes back online
    if (url.pathname === "/api/v1/health" || url.pathname === "/healthz") {
      try {
        const originResponse = await fetch(request);
        if (originResponse.status === 200) {
          return originResponse;
        }
      } catch (e) {
        // Origin is unreachable, fall back to maintenance
      }
    }

    // Route maintenance page based on subdomain
    let body = CONNECTO_MAIN_HTML;
    if (host.startsWith("news.")) {
      body = NEWS_HTML;
    } else if (host.startsWith("resinora.")) {
      body = RESINORA_HTML;
    }

    return new Response(body, {
      status: 503,
      statusText: "Service Unavailable",
      headers: {
        "Content-Type": "text/html;charset=UTF-8",
        "Cache-Control": "no-store, no-cache, must-revalidate",
        "Retry-After": "60",
        "X-Maintenance": "true"
      }
    });
  }
};
